package com.ethk3.novaonepro;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.security.MessageDigest;

/** Frozen predraw sidecar for the fixed nine B09 experts; excluded from Production canonical hash. */
public final class ResearchExpertPredrawSnapshotR811 {
    private static final long MAGIC=0x5238313145585031L; // R811EXP1
    public static final int SCHEMA_VERSION=1, EXPERT_COUNT=9;
    private ResearchExpertPredrawSnapshotR811(){}

    public static Snapshot freezeFromRuntime(V51RuntimeResult result){
        if(result==null||!result.success||result.context==null||result.numberModel==null||result.numberModel.experts==null||result.numberModel.experts.length!=EXPERT_COUNT||result.numberModel.gate==null||result.selected==null||result.selected.action==null)throw new IllegalArgumentException("R811_EXPERT_RUNTIME_INPUT");
        Expert[] experts=new Expert[EXPERT_COUNT];for(int i=0;i<EXPERT_COUNT;i++){V51Models.ExpertEvidence e=result.numberModel.experts[i];experts[i]=new Expert(e.expertId,e.rawScore,e.trust,e.uncertainty,e.signalStrength);}
        V51Models.PositionAction champion=result.selected.action;
        Snapshot snapshot=new Snapshot(result.context.baseIssue,result.context.targetIssue,result.context.historyHash,result.checksum,result.context.createdAt,champion.position,champion.n1,champion.n2,champion.n3,experts,result.numberModel.gate.weight,result.numberModel.gate.effectiveExperts,result.numberModel.gate.status.name());
        if(!verify(snapshot))throw new IllegalStateException("R811_EXPERT_SNAPSHOT_VERIFY");return snapshot;
    }

    public static boolean freezeFromRuntime(final DbStore store,V51RuntimeResult result){if(result==null)return false;return persist(store,freezeFromRuntime(result));}
    public static boolean persist(final DbStore store,final Snapshot s){if(store==null||s==null||RealtimePressureGateR811.hasActiveCriticalWork())return false;if(!store.coordinatorR36().ensureR811ResearchSchemaOnce())return false;final byte[]blob=encode(s);final String hash=hash(blob);Boolean out=store.coordinatorR36().runWrite("R811_EXPERT_PREDRAW",new DatabaseCoordinator.WriteCallable<Boolean>(){public Boolean call(SQLiteDatabase db){ContentValues cv=new ContentValues();cv.put("target_issue",s.targetIssue);cv.put("base_issue",s.baseIssue);cv.put("history_hash",s.historyHash);cv.put("canonical_hash",s.canonicalHash);cv.put("schema_version",SCHEMA_VERSION);cv.put("expert_count",EXPERT_COUNT);cv.put("blob",blob);cv.put("blob_sha256",hash);cv.put("frozen_at",s.frozenAt);cv.put("created_at",TimeSourceR811.wallNowMs());long row=db.insertWithOnConflict("v57_research_expert_predraw_r811",null,cv,SQLiteDatabase.CONFLICT_IGNORE);if(row>=0)return Boolean.TRUE;Cursor c=null;try{c=db.rawQuery("SELECT blob_sha256 FROM v57_research_expert_predraw_r811 WHERE target_issue=?",new String[]{s.targetIssue});return Boolean.valueOf(c.moveToFirst()&&hash.equals(c.getString(0)));}finally{if(c!=null)c.close();}}},Boolean.FALSE);return out.booleanValue();}
    public static Snapshot read(DbStore store,String target){if(store==null||!store.coordinatorR36().isR811ResearchSchemaReady())return null;Cursor c=null;try{c=store.readable().rawQuery("SELECT blob,blob_sha256 FROM v57_research_expert_predraw_r811 WHERE target_issue=? LIMIT 1",new String[]{target});if(!c.moveToFirst())return null;byte[]blob=c.getBlob(0);return hash(blob).equals(c.getString(1))?decode(blob):null;}finally{if(c!=null)c.close();}}

    public static byte[] encode(Snapshot s){if(!verify(s))throw new IllegalArgumentException("R811_EXPERT_SNAPSHOT_INVALID");try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeLong(MAGIC);out.writeInt(SCHEMA_VERSION);write(out,s.baseIssue);write(out,s.targetIssue);write(out,s.historyHash);write(out,s.canonicalHash);out.writeLong(s.frozenAt);out.writeInt(s.championPosition);out.writeInt(s.n1);out.writeInt(s.n2);out.writeInt(s.n3);out.writeInt(s.experts.length);for(Expert e:s.experts){write(out,e.expertId);writeMatrix(out,e.rawScore);writeArray(out,e.trust);writeArray(out,e.uncertainty);writeArray(out,e.signal);}writeMatrix(out,s.gateWeight);writeArray(out,s.effectiveExperts);write(out,s.gateStatus);out.flush();return bytes.toByteArray();}catch(Exception e){throw new IllegalStateException("R811_EXPERT_ENCODE",e);}}
    public static Snapshot decode(byte[]blob){try{DataInputStream in=new DataInputStream(new ByteArrayInputStream(blob));if(in.readLong()!=MAGIC||in.readInt()!=SCHEMA_VERSION)throw new IllegalStateException("R811_EXPERT_HEADER");String base=read(in),target=read(in),history=read(in),canonical=read(in);long frozen=in.readLong();int position=in.readInt(),n1=in.readInt(),n2=in.readInt(),n3=in.readInt(),count=in.readInt();if(count!=EXPERT_COUNT)throw new IllegalStateException("R811_EXPERT_COUNT");Expert[]experts=new Expert[count];for(int i=0;i<count;i++)experts[i]=new Expert(read(in),readMatrix(in,10,10),readArray(in,10),readArray(in,10),readArray(in,10));double[][]weight=readMatrix(in,10,EXPERT_COUNT);double[]neff=readArray(in,10);String status=read(in);if(in.available()!=0)throw new IllegalStateException("R811_EXPERT_TRAILING");Snapshot s=new Snapshot(base,target,history,canonical,frozen,position,n1,n2,n3,experts,weight,neff,status);if(!verify(s))throw new IllegalStateException("R811_EXPERT_VERIFY");return s;}catch(Exception e){throw new IllegalStateException("R811_EXPERT_DECODE",e);}}
    public static boolean verify(Snapshot s){if(s==null||!TargetIssueResolver.exact(s.baseIssue,s.targetIssue).valid||s.historyHash.length()!=64||s.canonicalHash.length()!=64||s.frozenAt<=0||s.experts.length!=EXPERT_COUNT||s.championPosition<1||s.championPosition>10||!DecisionGateEngine.b12K3(s.n1,s.n2,s.n3)||s.gateWeight.length!=10||s.effectiveExperts.length!=10||s.gateStatus.length()==0)return false;java.util.HashSet<String>ids=new java.util.HashSet<String>();for(int e=0;e<EXPERT_COUNT;e++){Expert x=s.experts[e];if(x==null||x.expertId.length()==0||!ids.add(x.expertId)||x.rawScore.length!=10||x.trust.length!=10||x.uncertainty.length!=10||x.signal.length!=10)return false;for(int p=0;p<10;p++){if(x.rawScore[p].length!=10||!finite(x.trust[p])||!finite(x.uncertainty[p])||!finite(x.signal[p]))return false;for(int n=0;n<10;n++)if(!finite(x.rawScore[p][n]))return false;}}for(int p=0;p<10;p++){if(s.gateWeight[p].length!=EXPERT_COUNT||!finite(s.effectiveExperts[p])||s.effectiveExperts[p]<0.0d)return false;for(int e=0;e<EXPERT_COUNT;e++)if(!finite(s.gateWeight[p][e])||s.gateWeight[p][e]<0.0d)return false;}return true;}

    public static final class Snapshot{public final String baseIssue,targetIssue,historyHash,canonicalHash,gateStatus;public final long frozenAt;public final int championPosition,n1,n2,n3;public final Expert[]experts;public final double[][]gateWeight;public final double[]effectiveExperts;Snapshot(String b,String t,String h,String c,long f,int p,int n1,int n2,int n3,Expert[]e,double[][]w,double[]neff,String status){baseIssue=safe(b);targetIssue=safe(t);historyHash=safe(h);canonicalHash=safe(c);frozenAt=f;championPosition=p;this.n1=n1;this.n2=n2;this.n3=n3;experts=e.clone();gateWeight=copy(w);effectiveExperts=neff.clone();gateStatus=safe(status);}}
    public static final class Expert{public final String expertId;public final double[][]rawScore;public final double[]trust,uncertainty,signal;Expert(String id,double[][]score,double[]trust,double[]uncertainty,double[]signal){expertId=safe(id);rawScore=copy(score);this.trust=trust==null?new double[0]:trust.clone();this.uncertainty=uncertainty==null?new double[0]:uncertainty.clone();this.signal=signal==null?new double[0]:signal.clone();}}
    private static double[][]copy(double[][]x){if(x==null)return new double[0][];double[][]y=new double[x.length][];for(int i=0;i<x.length;i++)y[i]=x[i]==null?new double[0]:x[i].clone();return y;}
    private static void write(DataOutputStream out,String x)throws Exception{byte[]b=safe(x).getBytes("UTF-8");out.writeInt(b.length);out.write(b);}private static String read(DataInputStream in)throws Exception{int n=in.readInt();if(n<0||n>65535)throw new IllegalStateException("R811_EXPERT_TEXT");byte[]b=new byte[n];in.readFully(b);return new String(b,"UTF-8");}
    private static void writeArray(DataOutputStream out,double[]x)throws Exception{out.writeInt(x.length);for(double v:x){if(Double.isNaN(v)||Double.isInfinite(v))throw new IllegalStateException("R811_EXPERT_NONFINITE");out.writeLong(Double.doubleToLongBits(v));}}private static double[]readArray(DataInputStream in,int expected)throws Exception{int n=in.readInt();if(n!=expected)throw new IllegalStateException("R811_EXPERT_ARRAY");double[]x=new double[n];for(int i=0;i<n;i++)x[i]=Double.longBitsToDouble(in.readLong());return x;}
    private static void writeMatrix(DataOutputStream out,double[][]x)throws Exception{out.writeInt(x.length);for(double[]row:x)writeArray(out,row);}private static double[][]readMatrix(DataInputStream in,int rows,int cols)throws Exception{int n=in.readInt();if(n!=rows)throw new IllegalStateException("R811_EXPERT_MATRIX");double[][]x=new double[n][];for(int i=0;i<n;i++)x[i]=readArray(in,cols);return x;}
    private static String hash(byte[]b){try{byte[]d=MessageDigest.getInstance("SHA-256").digest(b);StringBuilder s=new StringBuilder();for(byte v:d){int n=v&255;if(n<16)s.append('0');s.append(Integer.toHexString(n));}return s.toString();}catch(Exception e){throw new IllegalStateException(e);}}
    private static boolean finite(double x){return !Double.isNaN(x)&&!Double.isInfinite(x);}
    private static String safe(String x){return x==null?"":x.trim();}
}
